function renderHint(){for(const ui of Object.values(rotors))ui.button.classList.remove('suggested');const t=selectedTrain(),r=desiredRoute(t);if(r&&!station.route(r.id)){for(const [id,value]of Object.entries(r.req))if(station.points[id].value!==value)rotors[id]?.button.classList.add('suggested');if(!station.check(r))rotors[r.dir==='in'?r.side+'-in':r.id]?.button.classList.add('suggested');}if(!t){$('routehint').textContent='次の列車が接近すると指令が表示されます。';const next=station.plan.find(p=>!station.trains.some(t=>t.id===p.id));$('mission').textContent=next?`次は ${next.id} ${next.kind} ／ ${time(next.appear)} 接近予定`:'全列車の出発を確認してください。';$('guide').textContent='1・4番線は待避線、2・3番線は本線。上下直進は同時に扱えます。';return}
 $('mission').textContent=`${t.id} ${t.kind} ／ ${cardStatus(t)}`;$('guide').textContent=`所定 ${t.p}番線　到着 ${time(t.arr)} ／ 出発 ${time(t.dep)}　${t.note}`;
 if(!r&&t.loc.endsWith('AI')){$('routehint').textContent='閉塞信号は自動制御です。接近区間に進入したら場内信号テコを扱ってください。';return}if(!r){$('routehint').textContent='列車通過中。後尾がのど部を通過すると区分解錠されます。';return}const actual=station.route(r.id);let desc=`${r.side==='W'?'西方':'東方'}${r.dir==='in'?'場内':'出発'}・${r.p}番線`;const signalLabel=r.dir==='in'?`${r.side}A`:`${r.side==='W'?'WL':'ER'}${r.p}`;
 $('routehint').innerHTML=`<b>${desc}</b><br>① 白テコ ${station.assist(r.side,r.dir,r.p)}<br>② 転換完了の表示を確認<br>③ 赤テコ <b>${signalLabel}</b> を回す<br><span class="muted">${actual?'進路構成済み。停止現示を確認後、赤テコを定位Nに復位してください。':station.check(r)||'進路構成の条件が成立しています。'}</span>`;}
function actualCell(actual,due,p,expected){if(actual===null)return'<span class="muted">未</span>';const delay=Math.max(0,Math.round(actual-due));return`<span class="${delay>0||p!==expected?'late':'good'}">${time(actual)} ${p}番 ${delay?'+'+delay+'秒':'定時'}</span>`}
function renderTable(){const filter=$('tablefilter').value;writeHTML($('timetable'),station.plan.filter(p=>filter==='all'||p.from===filter).map(p=>{const r=station.records[p.id];const arrivalLate=r.arr===null?station.time>p.arr:r.arr>p.arr+.05,departureLate=r.dep===null?station.time>p.dep:r.dep>p.dep+.05;const mismatch=r.arrP!==null&&r.arrP!==p.p;const train=station.trains.find(t=>t.id===p.id);const status=r.dep!==null?'出発済':r.arr!==null?'到着済':train?'接近・進入中':station.time>=p.appear?'場外待機':'未接近';return`<tr class="${r.dep!==null?'finishedrow ':''}${selected===p.id?'selectedrow':''}"><td><span class="kind ${kindClass(p.kind)}">${p.kind}</span>${p.id}</td><td>${p.from==='W'?'下り':'上り'} ${p.from===p.to?'↩折返し':p.to==='E'?'東都→':'←西浜'}</td><td class="${mismatch?'late':''}">${mismatch?p.p+' → '+r.arrP+'番線':p.p+'番線'}</td><td>${time(p.prevDep)}</td><td class="${arrivalLate?'late':''}">${time(p.arr)}</td><td class="${departureLate?'late':''}">${time(p.dep)}</td><td>${actualCell(r.arr,p.arr,r.arrP,p.p)}</td><td>${actualCell(r.dep,p.dep,r.depP,p.p)}</td><td>${time(p.nextArr)}</td><td><span class="eventstatus">${status}</span></td></tr>`}).join(''))}

function lobby(){paused=true;$('modal').style.display='grid';$('modal').innerHTML=`<section class="modalbox"><div class="eyebrow">NEW SHIFT</div><h2>次の勤務を選ぶ</h2><p>現在の記録はCSVで保存できます。新しい勤務を始めると盤面と記録をリセットします。</p>${difficultyPicker()}<div class="modechoices">${[5,10,15].map(n=>`<button data-minutes="${n}" class="${n===minutes?'active':''}"><strong>${n}分</strong><small>${Rail.planFor(n,difficulty).length}列車</small></button>`).join('')}</div><div class="toolbar"><a class="station-select" href="index.html">駅選択</a><button id="returnshift">今の勤務に戻る</button><button id="start" class="primary">${minutes}分の勤務を始める</button></div></section>`;bindLobby();$('returnshift').onclick=()=>{$('modal').style.display='none';paused=false;render()}}
function difficultyPicker(){return '<div class="difficultychoices" aria-label="難易度">'+Object.entries(Rail.DIFFICULTIES).map(([key,d])=>`<button data-difficulty="${key}" class="${key===difficulty?'active':''}" aria-pressed="${key===difficulty}"><strong>${d.label}</strong><small>${d.description}</small></button>`).join('')+'</div><p class="difficulty-note">本数は上下合計です。ゆったり：片方向平均12本/時、標準：18本/時、高密度：24本/時相当。保安条件とゲーム内の時間の進み方は共通です。</p>';}
function bindLobby(){for(const b of document.querySelectorAll('[data-difficulty]'))b.onclick=()=>{difficulty=b.dataset.difficulty;for(const n of document.querySelectorAll('[data-difficulty]')){n.classList.toggle('active',n===b);n.setAttribute('aria-pressed',String(n===b));}for(const n of document.querySelectorAll('[data-minutes] small'))n.textContent=Rail.planFor(+n.parentElement.dataset.minutes,difficulty).length+'列車';if(!station.running&&!station.finished){station=new Rail.Station(minutes,difficulty);render()}};for(const b of document.querySelectorAll('[data-minutes]'))b.onclick=()=>{minutes=+b.dataset.minutes;for(const n of document.querySelectorAll('[data-minutes]'))n.classList.toggle('active',n===b);$('start').textContent=`${minutes}分の勤務を始める`;if(!station.running&&!station.finished){station=new Rail.Station(minutes,difficulty);render()}};$('start').onclick=start}
function start(){station=new Rail.Station(minutes,difficulty);station.begin();station.log(`${Rail.DIFFICULTIES[difficulty].label}・${minutes}分の勤務開始。ダイヤ列車 ${station.plan.length}本。`);selected=null;paused=false;seenResult=false;cardSignature='';$('modal').style.display='none';last=performance.now();station.step(.001);render()}
function showResults(){const r=station.result();paused=true;$('modal').style.display='grid';$('modal').innerHTML=`<section class="modalbox"><div class="eyebrow">SHIFT REPORT / ${Rail.DIFFICULTIES[station.difficulty].label} / ${station.minutes} MINUTES</div><div class="resulthead"><div><h2>青葉駅 勤務成績</h2><span class="muted">所定ダイヤに対する総合評価</span></div><div class="grade">${r.grade}<span style="font:20px system-ui"> ${r.score}点</span></div></div><div class="resultsgrid"><div class="resultmetric"><b>${Math.round(r.platform*100)}%</b><small>所定番線での発着 ${r.correct}/${r.total}</small></div><div class="resultmetric"><b>${Math.round(r.punctual*100)}%</b><small>15秒以内の定時発着 ${r.ontime}/${r.total}</small></div><div class="resultmetric"><b>${Math.round(r.completion*100)}%</b><small>発着完了 ${r.completed}/${r.total}</small></div><div class="resultmetric"><b>${secs(r.delay)}</b><small>延べ遅延（着・発の合計）</small></div><div class="resultmetric"><b>${secs(r.average)}</b><small>平均遅延／発着1回</small></div><div class="resultmetric"><b>${secs(r.max)}</b><small>最大遅延</small></div></div><p style="font-size:12px">ダイヤ通りに完了した列車：<b>${r.compliant} / ${r.rows.length}本</b>。番線30点＋定時35点＋完了35点。未完了の発着は番線・定時・完了の各項目で未達となり、遅延には終業時点の超過秒数を計上しています。番線一致と定時性はそれぞれ独立に採点します。</p><div class="tablewrap resulttable"><table><thead><tr><th>列車</th><th>番線 所定→実績</th><th>到着遅延</th><th>出発遅延</th><th>運転状況</th></tr></thead><tbody>${r.rows.map(t=>`<tr><td>${t.id} ${t.kind}</td><td>${t.p} → ${t.arrP??'—'} / ${t.depP??'—'}</td><td class="${t.arrDelay>15?'late':''}">${t.arrDelay===null?'未到着':secs(t.arrDelay)}</td><td class="${t.depDelay>15?'late':''}">${t.depDelay===null?'未出発':secs(t.depDelay)}</td><td>${t.dep===null?'未完了':t.arrP===t.p&&t.depP===t.p&&t.arrDelay<=15&&t.depDelay<=15?'所定通り':'実績確認'}</td></tr>`).join('')}</tbody></table></div><div class="resultactions"><a class="station-select" href="index.html">駅選択</a><button id="resultcsv">詳細記録CSV</button><button id="review">盤面を確認</button><button id="retry" class="primary">次の勤務</button></div></section>`;$('resultcsv').onclick=exportCSV;$('review').onclick=()=>{$('modal').style.display='none';};$('retry').onclick=lobby}
function exportCSV(){const fields=['列車','種別','出発側','所定番線','到着番線','出発番線','所定到着','実到着','到着遅延秒','所定出発','実出発','出発遅延秒','状況'];const lines=[fields.join(',')];for(const p of station.plan){const r=station.records[p.id];lines.push([p.id,p.kind,p.from==='W'?'下り':'上り',p.p,r.arrP??'',r.depP??'',time(p.arr),r.arr===null?'':time(r.arr),r.arr===null?'':Math.max(0,Math.round(r.arr-p.arr)),time(p.dep),r.dep===null?'':time(r.dep),r.dep===null?'':Math.max(0,Math.round(r.dep-p.dep)),r.dep===null?'未完了':'出発済'].join(','))}const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`青葉駅_${station.minutes}分_運転記録.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('pause').onclick=()=>{paused=!paused;render()};$('speed').onchange=()=>{speed=+$('speed').value};$('newshift').onclick=lobby;$('tablefilter').onchange=renderTable;$('export').onclick=exportCSV;$('fit').onclick=()=>{const fit=$('diagram').classList.toggle('fit');$('fit').textContent=fit?'操作サイズ':'全体表示'};buildDiagram();document.querySelector('#modal .modechoices').insertAdjacentHTML('beforebegin',difficultyPicker());for(const n of document.querySelectorAll('[data-minutes] small'))n.textContent=Rail.planFor(+n.parentElement.dataset.minutes,difficulty).length+'列車';bindLobby();render();
let audioElapsed=0;function frame(now){const dt=Math.min(.5,Math.max(0,(now-last)/1000));last=now;gameClock.advance(station,!paused&&!document.hidden&&station.running,speed,now);audioElapsed+=dt;if(audioElapsed>=.1){RailAudio.update(station,paused,audioElapsed,speed);audioElapsed=0;}if(!paused&&!document.hidden&&(station.running||station.finished&&!seenResult)&&now-lastRender>=200){render();lastRender=now}requestAnimationFrame(frame)}requestAnimationFrame(frame);



RailNavigation.install({active:()=>station.running&&!station.finished,suspend:()=>{const previous=paused;paused=true;RailAudio.update(station,true,0,speed);render();return()=>{paused=previous;gameClock.reset(performance.now());render();};}});

const trackLevers={'W-in':[150,270],'E-in':[1250,430]};for(let p=1;p<=4;p++){for(const[side,x]of[['W',550],['E',850]])trackLevers[side+'-out-'+p]=[x,Y[p],true];}Object.assign(trackLevers,{'11':[350,270],'12':[350,430],'13I':[200,270,true],'13R':[200,430],'21':[1050,270],'22':[1050,430],'23I':[1200,270,true],'23R':[1200,430]});RailOnTrack.place($('diagram'),rotors,trackLevers);

for(let p=1;p<=4;p++)for(const[side,x]of [['W',530],['E',870]]){const signal=signalNodes[side+'-out-'+p],y=Y[p]+20;signal.lamp.setAttribute('cx',x);signal.lamp.setAttribute('cy',y);signal.label.setAttribute('x',x+11);signal.label.setAttribute('y',y+3);}

signalNodes['E-in'].lamp.setAttribute('cx',1230);signalNodes['E-in'].lamp.setAttribute('cy',450);signalNodes['E-in'].label.setAttribute('x',1212);signalNodes['E-in'].label.setAttribute('y',453);

for(const[side,circuit,x,y]of [['W','1AT',134,330],['E','2AT',1265,510]]){
 const button=rotors[side+'-in'].button;button.closest('foreignObject').dataset.circuit=circuit;button.title=circuit+'の場内テコ。白テコで1〜4番線を選別します。';
 const label=[...$('diagram').querySelectorAll('.circuit-id')].find(e=>e.textContent===circuit);if(label){label.setAttribute('x',x);label.setAttribute('y',y);}
}


signalNodes['W-in'].lamp.setAttribute('cy',290);signalNodes['W-in'].label.setAttribute('y',293);
for(const side of ['W','E']){const circuit=side+'I';RailOnTrack.signalSide(rotors,side+'-in',circuit,tracks[circuit],circuitWindows[circuit].lamp);}
for(let p=1;p<=4;p++)for(const side of ['W','E'])RailOnTrack.signalSide(rotors,side+'-out-'+p,'P'+p,tracks['P'+p],circuitWindows['P'+p].lamp);

for(const [side,offset]of [['W',-40],['E',40]])rotors[side+'-in'].button.parentElement.querySelector('.rotor-label').style.transform='translateX('+offset+'px)';
